<?php
if(!defined('UNIOR_INICIADO')){http_response_code(403);exit;}
auth(true);
$evento=(int)($_GET['event_id']??0);$buscar=trim((string)($_GET['buscar']??''));$desde=trim((string)($_GET['desde']??''));$hasta=trim((string)($_GET['hasta']??''));
$condiciones=["pa.estado_abono='Confirmado'","pa.importe_abono>0"];$argumentos=[];
if($evento){$condiciones[]='r.event_id=?';$argumentos[]=$evento;}
if($buscar!==''){$condiciones[]="(CONCAT(r.first_name,' ',r.last_name) LIKE ? OR r.ci LIKE ? OR pa.codigo_transaccion LIKE ? OR CAST(pa.id AS CHAR)=?)";array_push($argumentos,'%'.$buscar.'%','%'.$buscar.'%','%'.$buscar.'%',$buscar);}
foreach(['desde'=>'>=','hasta'=>'<='] as $campo=>$operador){$valor=$$campo;if($valor!==''){if(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$valor)){http_response_code(400);exit('Fecha no válida.');}$condiciones[]='pa.fecha_verificacion'.$operador.'?';$argumentos[]=$valor.($campo==='desde'?' 00:00:00':' 23:59:59');}}
$consulta=' FROM pagos_inscripcion pa JOIN registrations r ON r.id=pa.id_titular JOIN events e ON e.id=r.event_id WHERE '.implode(' AND ',$condiciones);
$total=(int)q('SELECT COUNT(*)'.$consulta,$argumentos)->fetchColumn();$pagina=max(1,(int)($_GET['pagina']??1));
$filas=all('SELECT pa.id folio_pago,pa.importe_abono,pa.codigo_transaccion,pa.fecha_verificacion,pa.metodo_abono,r.token,r.first_name,r.last_name,r.tratamiento,r.ci,r.carrera,r.codigo_grupo,e.name evento_recibo'.$consulta.' ORDER BY pa.id DESC LIMIT 50 OFFSET '.(($pagina-1)*50),$argumentos);
headerPage('Recibos de pago · Imprimir y reimprimir'); ?>
<div class="card p-4 no-print"><p>Busque un pago por participante, CI, transacción o número de recibo. Cada abono conserva su propio recibo.</p><form method="get"><input type="hidden" name="p" value="recibos_pagos"><div class="row"><div class="col-md-4"><?php selectField('event_id','Evento',[0=>'Todos']+array_column(all('SELECT id,name FROM events ORDER BY starts_at DESC'),'name','id'),(string)$evento);?></div><div class="col-md-4"><?php field('buscar','Participante / CI / transacción / recibo',$buscar,'text',false);?></div><div class="col-md-2"><?php field('desde','Desde',$desde,'date',false);?></div><div class="col-md-2"><?php field('hasta','Hasta',$hasta,'date',false);?></div></div><button class="btn btn-primary">Buscar recibos</button> <a class="btn btn-outline-secondary" href="<?=url('p=recibos_pagos')?>">Limpiar filtros</a></form></div>
<div class="card p-3"><p><?=e($total)?> recibos encontrados</p><div class="table-responsive"><table class="table table-striped"><thead><tr><th>N.º</th><th>Fecha</th><th>Participante</th><th>Evento</th><th>Importe</th><th>Forma / transacción</th><th>Acciones</th></tr></thead><tbody><?php foreach($filas as $fila):?><tr><td>P-<?=str_pad((string)$fila['folio_pago'],7,'0',STR_PAD_LEFT)?></td><td><?=e($fila['fecha_verificacion'])?></td><td><?=e(nombreParticipante($fila))?><br>CI <?=e($fila['ci'])?><br><small><?=e($fila['carrera'])?><?=$fila['codigo_grupo']?' · Representante del grupo':''?></small></td><td><?=e($fila['evento_recibo'])?></td><td><?=money($fila['importe_abono'])?></td><td><?=e($fila['metodo_abono'])?><br><?=e($fila['codigo_transaccion'])?></td><td><a class="btn btn-sm btn-outline-primary" target="_blank" rel="noopener" href="<?=url('p=receipt&t='.$fila['token'].'&pago='.$fila['folio_pago'])?>">Ver recibo</a> <a class="btn btn-sm btn-primary" target="_blank" rel="noopener" href="<?=url('p=receipt&t='.$fila['token'].'&pago='.$fila['folio_pago'].'&imprimir=1')?>">Imprimir / reimprimir</a></td></tr><?php endforeach?><?php if(!$filas):?><tr><td colspan="7">No hay recibos para estos filtros.</td></tr><?php endif?></tbody></table></div><div class="no-print"><?php if($pagina>1):?><a class="btn btn-outline-primary" href="<?=url(http_build_query(array_merge($_GET,['pagina'=>$pagina-1])))?>">Anterior</a><?php endif?> Página <?=e($pagina)?><?php if($pagina*50<$total):?> <a class="btn btn-outline-primary" href="<?=url(http_build_query(array_merge($_GET,['pagina'=>$pagina+1])))?>">Siguiente</a><?php endif?></div></div>
<?php footerPage();
